import React, { useEffect, useMemo, useRef, useState } from "react";
import { AccessibilityInfo, PanResponder, View, type ViewStyle } from "react-native";
import { Canvas, Circle, Fill, Shader, Skia } from "@shopify/react-native-skia";
import { useDerivedValue, useFrameCallback, useSharedValue } from "react-native-reanimated";
import {
  COIN_DEFAULTS,
  coinAxes,
  createCoin,
  restCoin,
  stepCoinFixed,
  type CoinPointer,
  type CoinState,
} from "./coinMath";
import {
  COIN_BACKDROP_BOTTOM,
  COIN_BACKDROP_TOP,
  COIN_BACKGROUND,
  COIN_CAMERA,
  COIN_CENTER_X,
  COIN_CENTER_Y,
  COIN_H,
  COIN_METAL,
  COIN_PX_PER_UNIT,
  COIN_W,
} from "./coinDesign";
import { COIN_SHADER } from "./coinShader";

export type CoinProps = {
  slowMotion?: boolean;
  reducedMotion?: boolean;
  onFeedback?: (event: "grab" | "release") => void;
  label?: string;
  style?: ViewStyle;
};

const SKSL = `${COIN_SHADER}
half4 main(float2 p) {
  return half4(coinColor(p));
}
`;

let cachedEffect: ReturnType<typeof Skia.RuntimeEffect.Make> | undefined;
function getEffect() {
  if (cachedEffect === undefined) cachedEffect = Skia.RuntimeEffect.Make(SKSL);
  return cachedEffect;
}

function CanvasKeepAlive() {
  const [beat, setBeat] = useState(0);
  useEffect(() => {
    let cancelled = false;
    const tick = () => {
      if (cancelled) return;
      setBeat((b) => b + 1);
      requestAnimationFrame(tick);
    };
    const id = requestAnimationFrame(tick);
    return () => {
      cancelled = true;
      cancelAnimationFrame(id);
    };
  }, []);
  return (
    <View
      pointerEvents="none"
      style={{ position: "absolute", width: 1, height: 1, opacity: 0, transform: [{ translateX: beat % 2 }] }}
    />
  );
}

export function Coin({ slowMotion = false, reducedMotion, onFeedback, label = "Metal coin", style }: CoinProps) {
  const [systemReduce, setSystemReduce] = useState(false);
  const reduce = reducedMotion ?? systemReduce;
  const opts = useMemo(() => COIN_DEFAULTS, []);
  const effect = useMemo(() => getEffect(), []);
  const sim = useSharedValue<CoinState>(createCoin(opts));
  const frame = useSharedValue(0);
  const pointer = useSharedValue<CoinPointer>({ x: 0, y: 0, active: 0 });
  const slowM = useSharedValue(false);
  const reduceM = useSharedValue(false);
  const latest = useRef({ reduce, onFeedback });
  latest.current = { reduce, onFeedback };

  useEffect(() => {
    let alive = true;
    AccessibilityInfo.isReduceMotionEnabled()
      .then((v) => {
        if (alive) setSystemReduce(v);
      })
      .catch(() => {});
    const sub = AccessibilityInfo.addEventListener("reduceMotionChanged", setSystemReduce);
    return () => {
      alive = false;
      sub.remove();
    };
  }, []);
  useEffect(() => {
    slowM.value = slowMotion;
  }, [slowMotion, slowM]);
  useEffect(() => {
    reduceM.value = reduce;
    const fresh = createCoin(opts);
    if (reduce) restCoin(fresh, 0.7);
    sim.value = fresh;
    frame.value = frame.value + 1;
  }, [reduce, reduceM, sim, frame, opts]);

  const toWorld = (x: number, y: number): CoinPointer => ({
    x: (x - COIN_CENTER_X) / COIN_PX_PER_UNIT,
    y: -(y - COIN_CENTER_Y) / COIN_PX_PER_UNIT,
    active: 1,
  });
  const pan = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: () => !latest.current.reduce,
        onPanResponderGrant: (evt) => {
          pointer.value = toWorld(evt.nativeEvent.locationX, evt.nativeEvent.locationY);
          latest.current.onFeedback?.("grab");
        },
        onPanResponderMove: (evt) => {
          pointer.value = toWorld(evt.nativeEvent.locationX, evt.nativeEvent.locationY);
        },
        onPanResponderRelease: () => {
          pointer.value = { x: 0, y: 0, active: 0 };
          latest.current.onFeedback?.("release");
        },
        onPanResponderTerminate: () => {
          pointer.value = { x: 0, y: 0, active: 0 };
        },
        onPanResponderTerminationRequest: () => false,
      }),
    [pointer],
  );

  useFrameCallback((info) => {
    if (reduceM.value) return;
    const dt = Math.min(48, info.timeSincePreviousFrame ?? 16.7) / 1000;
    stepCoinFixed(sim.value, dt * (slowM.value ? 0.25 : 1), pointer.value, opts);
    frame.value = frame.value + 1;
  });

  const uniforms = useDerivedValue(() => {
    frame.value;
    const a = [0, 0, 0, 0, 0, 0, 0, 0, 0];
    coinAxes(sim.value, a);
    return {
      size: [COIN_W, COIN_H],
      center: [COIN_CENTER_X, COIN_CENTER_Y],
      ppu: COIN_PX_PER_UNIT,
      camD: COIN_CAMERA,
      ax: [a[0], a[1], a[2]],
      ay: [a[3], a[4], a[5]],
      az: [a[6], a[7], a[8]],
      metal: COIN_METAL,
      bgTop: COIN_BACKDROP_TOP,
      bgBottom: COIN_BACKDROP_BOTTOM,
    };
  });

  return (
    <View
      style={[{ width: COIN_W, height: COIN_H, borderRadius: 18, overflow: "hidden", backgroundColor: COIN_BACKGROUND }, style]}
      accessibilityLabel={label}
      accessibilityRole="image"
      {...pan.panHandlers}
    >
      {!reduce ? <CanvasKeepAlive /> : null}
      <Canvas pointerEvents="none" style={{ width: COIN_W, height: COIN_H }}>
        {effect ? (
          <Fill>
            <Shader source={effect} uniforms={uniforms} />
          </Fill>
        ) : (
          <Circle cx={COIN_CENTER_X} cy={COIN_CENTER_Y} r={COIN_PX_PER_UNIT} color="#c9ccd2" />
        )}
      </Canvas>
    </View>
  );
}

export type CoinPointer = { x: number; y: number; active: number };

export const COIN_DEFAULTS = {
  radius: 1,
  halfThickness: 0.1,
  mass: 1,
  fixedDt: 1 / 480,
  damping: 0.2,
  grabStiffness: 46,
  grabDamping: 7,
  maxForce: 60,
  maxOmega: 26,
  velocitySmoothing: 0.35,
  startOmega1: 1.1,
  startOmega2: 0.45,
  startOmega3: 5.2,
  startTilt: 0.5,
};

export type CoinOptions = typeof COIN_DEFAULTS;

export type CoinState = {
  qw: number;
  qx: number;
  qy: number;
  qz: number;
  w1: number;
  w2: number;
  w3: number;
  time: number;
  acc: number;
  grabbed: number;
  gx: number;
  gy: number;
  gz: number;
  tx: number;
  ty: number;
  vx: number;
  vy: number;
};

export function coinInertia(opts: CoinOptions) {
  "worklet";
  const r2 = opts.radius * opts.radius;
  const h = opts.halfThickness * 2;
  return {
    transverse: opts.mass * (r2 / 4 + (h * h) / 12),
    axial: (opts.mass * r2) / 2,
  };
}

export function createCoin(opts: CoinOptions): CoinState {
  "worklet";
  const half = opts.startTilt / 2;
  return {
    qw: Math.cos(half),
    qx: Math.sin(half),
    qy: 0,
    qz: 0,
    w1: opts.startOmega1,
    w2: opts.startOmega2,
    w3: opts.startOmega3,
    time: 0,
    acc: 0,
    grabbed: 0,
    gx: 0,
    gy: 0,
    gz: 0,
    tx: 0,
    ty: 0,
    vx: 0,
    vy: 0,
  };
}

export function restCoin(s: CoinState, tilt: number) {
  "worklet";
  const half = tilt / 2;
  s.qw = Math.cos(half);
  s.qx = Math.sin(half);
  s.qy = Math.sin(half) * 0.4;
  s.qz = 0;
  const n = Math.sqrt(s.qw * s.qw + s.qx * s.qx + s.qy * s.qy + s.qz * s.qz);
  s.qw /= n;
  s.qx /= n;
  s.qy /= n;
  s.w1 = 0;
  s.w2 = 0;
  s.w3 = 0;
  s.grabbed = 0;
}

export function rotate(q: { qw: number; qx: number; qy: number; qz: number }, x: number, y: number, z: number, out: number[]) {
  "worklet";
  const { qw, qx, qy, qz } = q;
  const tx = 2 * (qy * z - qz * y);
  const ty = 2 * (qz * x - qx * z);
  const tz = 2 * (qx * y - qy * x);
  out[0] = x + qw * tx + (qy * tz - qz * ty);
  out[1] = y + qw * ty + (qz * tx - qx * tz);
  out[2] = z + qw * tz + (qx * ty - qy * tx);
}

export function rotateInverse(q: { qw: number; qx: number; qy: number; qz: number }, x: number, y: number, z: number, out: number[]) {
  "worklet";
  rotate({ qw: q.qw, qx: -q.qx, qy: -q.qy, qz: -q.qz }, x, y, z, out);
}

export function coinAxes(s: CoinState, out: number[]) {
  "worklet";
  const v = [0, 0, 0];
  rotate(s, 1, 0, 0, v);
  out[0] = v[0];
  out[1] = v[1];
  out[2] = v[2];
  rotate(s, 0, 1, 0, v);
  out[3] = v[0];
  out[4] = v[1];
  out[5] = v[2];
  rotate(s, 0, 0, 1, v);
  out[6] = v[0];
  out[7] = v[1];
  out[8] = v[2];
}

export function kineticEnergy(s: CoinState, opts: CoinOptions) {
  "worklet";
  const { transverse, axial } = coinInertia(opts);
  return 0.5 * (transverse * (s.w1 * s.w1 + s.w2 * s.w2) + axial * s.w3 * s.w3);
}

export function angularMomentumBody(s: CoinState, opts: CoinOptions, out: number[]) {
  "worklet";
  const { transverse, axial } = coinInertia(opts);
  out[0] = transverse * s.w1;
  out[1] = transverse * s.w2;
  out[2] = axial * s.w3;
}

export function angularMomentumWorld(s: CoinState, opts: CoinOptions, out: number[]) {
  "worklet";
  const b = [0, 0, 0];
  angularMomentumBody(s, opts, b);
  rotate(s, b[0], b[1], b[2], out);
}

function derivative(y: number[], t1: number, t2: number, t3: number, i1: number, i3: number, out: number[]) {
  "worklet";
  const w1 = y[0];
  const w2 = y[1];
  const w3 = y[2];
  const qw = y[3];
  const qx = y[4];
  const qy = y[5];
  const qz = y[6];
  out[0] = ((i1 - i3) * w2 * w3 + t1) / i1;
  out[1] = ((i3 - i1) * w3 * w1 + t2) / i1;
  out[2] = t3 / i3;
  out[3] = 0.5 * (-qx * w1 - qy * w2 - qz * w3);
  out[4] = 0.5 * (qw * w1 + qy * w3 - qz * w2);
  out[5] = 0.5 * (qw * w2 + qz * w1 - qx * w3);
  out[6] = 0.5 * (qw * w3 + qx * w2 - qy * w1);
}

export function rk4Step(s: CoinState, dt: number, t1: number, t2: number, t3: number, opts: CoinOptions) {
  "worklet";
  const { transverse, axial } = coinInertia(opts);
  const y0 = [s.w1, s.w2, s.w3, s.qw, s.qx, s.qy, s.qz];
  const k1 = [0, 0, 0, 0, 0, 0, 0];
  const k2 = [0, 0, 0, 0, 0, 0, 0];
  const k3 = [0, 0, 0, 0, 0, 0, 0];
  const k4 = [0, 0, 0, 0, 0, 0, 0];
  const tmp = [0, 0, 0, 0, 0, 0, 0];
  derivative(y0, t1, t2, t3, transverse, axial, k1);
  for (let i = 0; i < 7; i++) tmp[i] = y0[i] + 0.5 * dt * k1[i];
  derivative(tmp, t1, t2, t3, transverse, axial, k2);
  for (let i = 0; i < 7; i++) tmp[i] = y0[i] + 0.5 * dt * k2[i];
  derivative(tmp, t1, t2, t3, transverse, axial, k3);
  for (let i = 0; i < 7; i++) tmp[i] = y0[i] + dt * k3[i];
  derivative(tmp, t1, t2, t3, transverse, axial, k4);
  const y = [0, 0, 0, 0, 0, 0, 0];
  for (let i = 0; i < 7; i++) y[i] = y0[i] + (dt / 6) * (k1[i] + 2 * k2[i] + 2 * k3[i] + k4[i]);
  const n = Math.sqrt(y[3] * y[3] + y[4] * y[4] + y[5] * y[5] + y[6] * y[6]);
  s.w1 = y[0];
  s.w2 = y[1];
  s.w3 = y[2];
  s.qw = y[3] / n;
  s.qx = y[4] / n;
  s.qy = y[5] / n;
  s.qz = y[6] / n;
  s.time += dt;
}

export function grabCoin(s: CoinState, x: number, y: number, opts: CoinOptions) {
  "worklet";
  const n = [0, 0, 0];
  rotate(s, 0, 0, 1, n);
  let z = 0;
  if (Math.abs(n[2]) > 0.15) z = -(n[0] * x + n[1] * y) / n[2];
  let px = x;
  let py = y;
  const len = Math.sqrt(px * px + py * py + z * z);
  const limit = opts.radius;
  if (len > limit) {
    px = (px * limit) / len;
    py = (py * limit) / len;
    z = (z * limit) / len;
  }
  const b = [0, 0, 0];
  rotateInverse(s, px, py, z, b);
  const side = n[2] >= 0 ? 1 : -1;
  s.gx = b[0];
  s.gy = b[1];
  s.gz = side * opts.halfThickness;
  s.grabbed = 1;
  s.tx = x;
  s.ty = y;
  s.vx = 0;
  s.vy = 0;
}

function gripTorque(s: CoinState, opts: CoinOptions, out: number[]) {
  "worklet";
  const rw = [0, 0, 0];
  rotate(s, s.gx, s.gy, s.gz, rw);
  const wb = [s.w1, s.w2, s.w3];
  const ww = [0, 0, 0];
  rotate(s, wb[0], wb[1], wb[2], ww);
  const vcx = ww[1] * rw[2] - ww[2] * rw[1];
  const vcy = ww[2] * rw[0] - ww[0] * rw[2];
  let fx = opts.grabStiffness * (s.tx - rw[0]) + opts.grabDamping * (s.vx - vcx);
  let fy = opts.grabStiffness * (s.ty - rw[1]) + opts.grabDamping * (s.vy - vcy);
  const f = Math.sqrt(fx * fx + fy * fy);
  if (f > opts.maxForce) {
    fx = (fx * opts.maxForce) / f;
    fy = (fy * opts.maxForce) / f;
  }
  const tw = [rw[1] * 0 - rw[2] * fy, rw[2] * fx - rw[0] * 0, rw[0] * fy - rw[1] * fx];
  rotateInverse(s, tw[0], tw[1], tw[2], out);
}

export function stepCoinFixed(s: CoinState, dt: number, pointer: CoinPointer, opts: CoinOptions) {
  "worklet";
  const frame = Math.min(0.05, Math.max(0, dt));
  if (pointer.active) {
    if (!s.grabbed) grabCoin(s, pointer.x, pointer.y, opts);
    else if (frame > 0) {
      const a = opts.velocitySmoothing;
      s.vx += ((pointer.x - s.tx) / frame - s.vx) * a;
      s.vy += ((pointer.y - s.ty) / frame - s.vy) * a;
      s.tx = pointer.x;
      s.ty = pointer.y;
    }
  } else if (s.grabbed) {
    s.grabbed = 0;
  }
  const { transverse, axial } = coinInertia(opts);
  s.acc += frame;
  const h = opts.fixedDt;
  const torque = [0, 0, 0];
  while (s.acc >= h) {
    torque[0] = 0;
    torque[1] = 0;
    torque[2] = 0;
    if (s.grabbed) gripTorque(s, opts, torque);
    torque[0] -= opts.damping * transverse * s.w1;
    torque[1] -= opts.damping * transverse * s.w2;
    torque[2] -= opts.damping * axial * s.w3;
    rk4Step(s, h, torque[0], torque[1], torque[2], opts);
    const w = Math.sqrt(s.w1 * s.w1 + s.w2 * s.w2 + s.w3 * s.w3);
    if (w > opts.maxOmega) {
      const k = opts.maxOmega / w;
      s.w1 *= k;
      s.w2 *= k;
      s.w3 *= k;
    }
    s.acc -= h;
  }
}

export const COIN_SHADER = `
uniform float2 size;
uniform float2 center;
uniform float ppu;
uniform float camD;
uniform float3 ax;
uniform float3 ay;
uniform float3 az;
uniform float3 metal;
uniform float3 bgTop;
uniform float3 bgBottom;

const float RB = 0.045;
const float HALF = 0.1;

float3 toBody(float3 v) {
  return float3(dot(v, ax), dot(v, ay), dot(v, az));
}

float3 toWorld(float3 v) {
  return ax * v.x + ay * v.y + az * v.z;
}

float relief(float2 q) {
  float rho = length(q);
  float ang = atan(q.y, q.x);
  float rim = smoothstep(0.80, 0.84, rho) * (1.0 - smoothstep(0.93, 0.97, rho));
  float inner = 1.0 - smoothstep(0.64, 0.68, rho);
  float lobe = 0.5 + 0.5 * cos(ang * 6.0);
  float starR = 0.16 + 0.34 * lobe * lobe;
  float emblem = 1.0 - smoothstep(starR - 0.02, starR + 0.02, rho);
  float dd = (rho - 0.56) / 0.012;
  float ring = exp(-dd * dd);
  return 0.022 * rim - 0.010 * inner + 0.018 * emblem + 0.006 * ring;
}

float baseSdf(float3 p) {
  float2 q = float2(length(p.xy) - (1.0 - RB), abs(p.z) - (HALF - RB));
  return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - RB;
}

float map(float3 p) {
  float d = baseSdf(p);
  if (d < 0.06) {
    float rho = length(p.xy);
    float az1 = abs(p.z);
    float faceMask = smoothstep(HALF - 0.06, HALF - 0.02, az1);
    float sideMask = smoothstep(1.0 - RB - 0.02, 1.0 - RB + 0.01, rho) * (1.0 - smoothstep(HALF - RB - 0.02, HALF - RB + 0.005, az1));
    float reed = 0.5 + 0.5 * cos(atan(p.y, p.x) * 72.0);
    d = d - relief(p.xy) * faceMask - reed * 0.007 * sideMask;
  }
  return d;
}

float3 calcNormal(float3 p) {
  float e = 0.0035;
  return normalize(float3(
    map(p + float3(e, 0.0, 0.0)) - map(p - float3(e, 0.0, 0.0)),
    map(p + float3(0.0, e, 0.0)) - map(p - float3(0.0, e, 0.0)),
    map(p + float3(0.0, 0.0, e)) - map(p - float3(0.0, 0.0, e))));
}

float3 env(float3 d) {
  float up = d.y * 0.5 + 0.5;
  float3 col = mix(float3(0.2, 0.21, 0.24), float3(0.6, 0.65, 0.74), smoothstep(0.0, 1.0, up));
  float3 key = normalize(float3(-0.55, 0.75, 0.55));
  col += float3(1.7, 1.62, 1.5) * smoothstep(0.8, 0.95, dot(d, key));
  float3 strip = normalize(float3(0.9, 0.15, 0.3));
  col += float3(0.45, 0.6, 0.9) * smoothstep(0.7, 0.96, dot(d, strip));
  float3 front = normalize(float3(0.15, 0.3, 1.0));
  col += float3(0.5, 0.52, 0.58) * smoothstep(0.7, 0.99, dot(d, front));
  float3 fill = normalize(float3(0.1, -0.8, 0.4));
  col += float3(0.5, 0.32, 0.18) * 0.25 * smoothstep(0.6, 0.95, dot(d, fill));
  col += float3(0.12, 0.12, 0.13) * exp(-abs(d.y) * 14.0);
  return col;
}

float3 backdrop(float2 p) {
  float t = clamp(p.y / size.y, 0.0, 1.0);
  float3 col = mix(bgTop, bgBottom, t);
  float2 g = (p - center) / (size.y * 0.55);
  col += float3(0.05, 0.06, 0.09) * exp(-dot(g, g) * 1.4);
  float2 s = float2((p.x - center.x) / (1.05 * ppu), (p.y - (center.y + 1.5 * ppu)) / (0.5 * ppu));
  col *= 1.0 - 0.3 * exp(-dot(s, s));
  return col;
}

float4 coinColor(float2 p) {
  float3 bg = backdrop(p);
  float2 uv = (p - center) / ppu;
  uv.y = -uv.y;
  float3 ro = float3(0.0, 0.0, camD);
  float3 rd = normalize(float3(uv.x, uv.y, -camD));
  float b = dot(ro, rd);
  float c = dot(ro, ro) - 1.2544;
  float disc = b * b - c;
  if (disc < 0.0) return float4(bg, 1.0);
  float root = sqrt(disc);
  float t = -b - root;
  float tEnd = -b + root;
  float pix = 1.0 / ppu;
  float minN = 1000.0;
  float tMin = t;
  float hit = 0.0;
  for (int i = 0; i < 64; i++) {
    float3 pb = toBody(ro + rd * t);
    float d = map(pb);
    float dn = d / (pix * t / camD);
    if (dn < minN) {
      minN = dn;
      tMin = t;
    }
    if (d < 0.0008) {
      hit = 1.0;
      tMin = t;
      break;
    }
    t += d * 0.85;
    if (t > tEnd) break;
  }
  float cover = hit > 0.5 ? 1.0 : 1.0 - smoothstep(0.0, 1.2, minN);
  if (cover <= 0.0) return float4(bg, 1.0);
  float3 pb = toBody(ro + rd * tMin);
  float3 nb = calcNormal(pb);
  float3 n = toWorld(nb);
  float3 v = -rd;
  float ndv = max(dot(n, v), 0.0);
  float3 f = metal + (1.0 - metal) * pow(1.0 - ndv, 5.0);
  float3 r = reflect(rd, n);
  float3 sharp = env(r);
  float3 soft = env(normalize(r + 0.18 * n));
  float3 col = (sharp * 0.65 + soft * 0.35) * f;
  col += metal * 0.04 * env(n);
  float h = relief(pb.xy);
  float onFace = smoothstep(HALF - 0.04, HALF - 0.01, abs(pb.z));
  col *= 1.0 + 12.0 * clamp(h, -0.012, 0.0) * onFace;
  float groove = 0.5 + 0.5 * cos(length(pb.xy) * 260.0);
  col *= 1.0 - 0.05 * groove * onFace;
  col = 1.0 - exp(-col * 1.5);
  return float4(mix(bg, col, cover), 1.0);
}
`;

